"  const getYAxisTicks = (maxVal) => {
    if (!maxVal || maxVal < 0) {
      return [0, 1000];
    }
    let step = 200;
    if (maxVal > 1000) {
      const rawStep = maxVal / 5;
      step = Math.ceil(rawStep / 1000) * 1000;
    } else {
      const rawStep = maxVal / 5;
      step = Math.ceil(rawStep / 200) * 200;
      if (step < 200) step = 200;
    }
    const ticksCount = Math.ceil(maxVal / step);
    const ticks = [];
    for (let i = 0; i <= ticksCount; i++) {
      ticks.push(i * step);
    }
    if (ticks.length < 2) {
      return [0, step];
    }
    return ticks;
  };"
